class DinnerPlates(private val capacity:Int) { private val stacks=mutableListOf<java.util.ArrayDeque<Int>>();private val available=java.util.TreeSet<Int>();fun push(`val`:Int){val index=if(available.isEmpty()){stacks.add(java.util.ArrayDeque());stacks.lastIndex}else available.first();val stack=stacks[index];stack.push(`val`);if(stack.size==capacity)available.remove(index) else available.add(index)};fun pop():Int=if(stacks.isEmpty())-1 else popAtStack(stacks.lastIndex);fun popAtStack(index:Int):Int{if(index !in stacks.indices||stacks[index].isEmpty())return -1;val value=stacks[index].pop();available.add(index);while(stacks.isNotEmpty()&&stacks.last().isEmpty()){val last=stacks.lastIndex;stacks.removeAt(last);available.remove(last)};return value} }
